5	// Test implementation of BaseCSVParser for testing protected methods
6	class TestCSVParser extends BaseCSVParser {
7		parse(csvContent: string): CSVParseResult {
8			return { transactions: [], errors: [] };
9		}
10	
11		validateFormat(csvContent: string): boolean {
12			return true;
13		}
14	
15		// Expose protected methods for testing
16		public testNormalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
17			return this.normalizeAmount(amount, invertSign);
18		}
19	}
20	
21	describe('BaseCSVParser', () => {
22		const parser = new TestCSVParser();
23	
24		describe('normalizeAmount - #{#trn1b}', () => {
25			describe('when invertSign is true (for banks like Amex where positive = expense in CSV)', () => {
26				it('should convert positive expense to negative', () => {
27					// American Express: 50.00 (expense in CSV) → -50.00 (negative = expense)
28					expect(parser.testNormalizeAmount(-50.0, true)).toBe(50.0);
29				});
30	
31				it('should convert negative refund to positive', () => {
32					// American Express: -25.00 (refund in CSV) → 25.00 (positive = refund)
33					expect(parser.testNormalizeAmount(25.0, true)).toBe(-25.0);
34				});
35	
36				it('should handle large negative amounts', () => {
37					expect(parser.testNormalizeAmount(-1234.56, true)).toBe(1234.56);
38				});
39	
40				it('should handle large positive amounts', () => {
41					expect(parser.testNormalizeAmount(9999.99, true)).toBe(-9999.99);
42				});
43	
44				it('should handle amounts with many decimals', () => {
45					expect(parser.testNormalizeAmount(-123.456789, true)).toBe(123.456789);
46				});
47			});
48	
49			describe('when invertSign is false (for banks already using negative for expenses)', () => {
50				it('should keep negative expense as negative', () => {
51					// PC Financial: -50.00 (expense) → -50.00 (negative = expense)
52					expect(parser.testNormalizeAmount(50.0, false)).toBe(50.0);
53				});
54	
55				it('should keep positive refund as positive', () => {
56					// PC Financial: 25.00 (refund) → 25.00 (positive = refund)
57					expect(parser.testNormalizeAmount(-25.0, false)).toBe(-25.0);
58				});
59	
60				it('should handle large amounts unchanged', () => {
61					expect(parser.testNormalizeAmount(5000.0, false)).toBe(5000.0);
62					expect(parser.testNormalizeAmount(-5000.0, false)).toBe(-5000.0);
63				});
64			});
65	
66			describe('edge cases', () => {
67				it('should handle null amount', () => {
68					expect(parser.testNormalizeAmount(null, true)).toBeNull();
69					expect(parser.testNormalizeAmount(null, false)).toBeNull();
70				});
71	
72				it('should handle zero amount with invertSign true', () => {
73					expect(parser.testNormalizeAmount(0, true)).toBe(0);
74				});
75	
76				it('should handle zero amount with invertSign false', () => {
77					expect(parser.testNormalizeAmount(0, false)).toBe(0);
78				});
79	
80				it('should handle negative zero', () => {
81					expect(parser.testNormalizeAmount(-0, true)).toBe(0);
82					expect(parser.testNormalizeAmount(-0, false)).toBe(0);
83				});
84	
85				it('should handle very small amounts', () => {
86					expect(parser.testNormalizeAmount(-0.01, true)).toBe(0.01);
87					expect(parser.testNormalizeAmount(0.01, true)).toBe(-0.01);
88				});
89	
90				it('should handle very large amounts', () => {
91					expect(parser.testNormalizeAmount(-999999.99, true)).toBe(999999.99);
92					expect(parser.testNormalizeAmount(999999.99, false)).toBe(999999.99);
93				});
94			});
95	
96			describe('default parameter behavior', () => {
97				it('should default invertSign to true when not specified', () => {
98					// Default should invert sign
99					expect(parser.testNormalizeAmount(-50.0)).toBe(50.0);
100					expect(parser.testNormalizeAmount(25.0)).toBe(-25.0);
101				});
102			});
103		});
104	});
