2	// Automatically selects and returns the appropriate parser based on credit card type or CSV format
3	
4	import type { CreditCardType } from '$lib/models/Transaction';
5	import type { ICSVParser } from './BaseCSVParser';
6	import { PCFinancialParser } from './PCFinancialParser';
7	import { AmexParser } from './AmexParser';
8	import { RBCFinancialParser } from './RBCFinancialParser';
9	import { TDBankParser } from './TDBankParser';
10	import { SimpliiFinancialParser } from './SimpliiFinancialParser';
11	import { EQBankParser } from './EQBankParser';
12	import { WealthSimpleParser } from './WealthSimpleParser'; // #{#wsp3b}
13	
14	export class CSVParserFactory {
15		/**
16		 * Get a parser for a specific credit card type
17		 */
18		static getParser(creditCardType: CreditCardType): ICSVParser {
19			switch (creditCardType) {
20				case 'PC Financial':
21					return new PCFinancialParser();
22				case 'American Express':
23					return new AmexParser();
24				case 'RBC Financial':
25					return new RBCFinancialParser();
26				case 'TD Bank':
27					return new TDBankParser();
28				case 'Simplii Financial':
29					return new SimpliiFinancialParser();
30				case 'EQ Bank':
31					return new EQBankParser();
32				case 'Wealth Simple': // #{#wsp3b}
33					return new WealthSimpleParser();
34				default:
35					throw new Error(`Unsupported credit card type: ${creditCardType}`);
36			}
37		}
38	
39		/**
40		 * Auto-detect the appropriate parser based on CSV content
41		 * Returns the parser and credit card type, or null if no match
42		 */
43		static detectParser(csvContent: string): {
44			parser: ICSVParser;
45			creditCardType: CreditCardType;
46		} | null {
47			// Order matters! Check more specific formats first before generic ones
48			// TD Bank has no header, so it needs to be checked last
49			const parsers: Array<{ parser: ICSVParser; type: CreditCardType }> = [
50				{ parser: new AmexParser(), type: 'American Express' },
51				{ parser: new PCFinancialParser(), type: 'PC Financial' },
52				{ parser: new RBCFinancialParser(), type: 'RBC Financial' },
53				{ parser: new SimpliiFinancialParser(), type: 'Simplii Financial' },
54				{ parser: new EQBankParser(), type: 'EQ Bank' },
55				{ parser: new WealthSimpleParser(), type: 'Wealth Simple' }, // #{#wsp3b}
56				{ parser: new TDBankParser(), type: 'TD Bank' } // Last - has no header, most generic
57			];
58	
59			// Try each parser's validation method
60			for (const { parser, type } of parsers) {
61				if (parser.validateFormat(csvContent)) {
62					return { parser, creditCardType: type };
63				}
64			}
65	
66			return null;
67		}
68	
69		/**
70		 * Get all available parsers
71		 */
72		static getAllParsers(): Array<{ parser: ICSVParser; type: CreditCardType }> {
73			return [
74				{ parser: new PCFinancialParser(), type: 'PC Financial' },
75				{ parser: new AmexParser(), type: 'American Express' },
76				{ parser: new RBCFinancialParser(), type: 'RBC Financial' },
77				{ parser: new TDBankParser(), type: 'TD Bank' },
78				{ parser: new SimpliiFinancialParser(), type: 'Simplii Financial' },
79				{ parser: new EQBankParser(), type: 'EQ Bank' },
80				{ parser: new WealthSimpleParser(), type: 'Wealth Simple' } // #{#wsp3b}
81			];
82		}
83	}
